mapper.select:
SELECT id, public_id, vehicle_id, created_at
FROM trip
WHERE status = 'ACTIVE' AND last_activity_at < #{idleBefore}

mapper.update:
UPDATE waypoint_request wr JOIN trip t ON t.id = wr.trip_id
SET wr.status = #{to}, wr.decided_at = #{now}, wr.fail_reason = #{failReason}
WHERE wr.id = #{requestId} AND t.vehicle_id = #{vehicleId} AND wr.status = #{from}
	AND wr.requested_at >= #{requestedSince}
